let seed = 987654;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const ri = (a, b) => a + Math.floor(rnd() * (b - a + 1));
const pick = (xs) => xs[ri(0, xs.length - 1)];
const canon = (v) => JSON.stringify(v, (k, x) => (x && typeof x === 'object' && !Array.isArray(x) ? Object.fromEntries(Object.keys(x).sort().map((kk) => [kk, x[kk]])) : x));
const clone = (v) => JSON.parse(JSON.stringify(v));
const KEYS = ['a', 'b', 'size', 'theme', 'accent', 'x1', 'items', 'nested'];
const scalar = () => pick([() => 'str' + ri(0, 9), () => ri(-5, 99), () => rnd() < 0.5, () => null])();
function plainObj(d) { const o = {}; const n = ri(0, 4); for (let i = 0; i < n; i++) o[pick(KEYS)] = anyValue(d); return o; }
function anyValue(d) { const r = rnd(); if (r < 0.4 || d >= 3) return scalar(); if (r < 0.6) return plainObj(d + 1); return arrValue(d); }
function arrValue(d) { const n = ri(0, 4); if (rnd() < 0.5) return Array.from({ length: n }, () => scalar()); return Array.from({ length: n }, () => plainObj(d + 1)); }
function patchValue(v) {
  if (Array.isArray(v)) { const n = ri(0, 4); if (v.length && typeof v[0] === 'object' && v[0] !== null) return Array.from({ length: n }, (_, i) => (i < v.length && rnd() < 0.8 ? patchObj(v[i]) : plainObj(2))); return Array.from({ length: n }, () => scalar()); }
  if (v !== null && typeof v === 'object') return patchObj(v);
  return scalar();
}
function patchObj(base) { const p = {}; for (const k of Object.keys(base)) if (rnd() < 0.7) p[k] = patchValue(base[k]); const fresh = KEYS.filter((k) => !(k in base)); if (fresh.length && rnd() < 0.5) p[pick(fresh)] = anyValue(1); return p; }
const TCH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 _-.';
const genTitle = () => { let s = ''; const n = ri(0, 40); for (let i = 0; i < n; i++) s += TCH[ri(0, TCH.length - 1)]; return s; };
const genPairs = () => Array.from({ length: ri(0, 8) }, () => [Array.from({ length: ri(1, 5) }, () => String.fromCharCode(97 + ri(0, 5))).join(''), ri(-100, 100)]);

const bad = { apply: [], title: [], lookup: [] };
const N_ITER = 50000;
for (let i = 0; i < N_ITER; i++) {
  const base = plainObj(1); const patch = patchObj(base);
  const a = O.applyPatch(clone(base), clone(patch)); const b = N.applyPatch(clone(base), clone(patch));
  if (canon(a) !== canon(b)) bad.apply.push([canon(base), canon(patch)]);
  const s = genTitle();
  if (O.toTitle(s) !== N.toTitle(s)) bad.title.push([s, O.toTitle(s), N.toTitle(s)]);
  const p = genPairs();
  if (canon(O.toLookup(p)) !== canon(N.toLookup(p))) bad.lookup.push(p);
}
// examples from the task
const ex = [
  [O.applyPatch({}, { size: 'compact' }), N.applyPatch({}, { size: 'compact' })],
  [O.applyPatch({ accent: null }, { accent: null, theme: 'blue' }), N.applyPatch({ accent: null }, { accent: null, theme: 'blue' })],
];
console.log('examples equal:', ex.every(([a, b]) => canon(a) === canon(b)), canon(ex[1][0]));
console.log('title examples:', JSON.stringify(O.toTitle('')), JSON.stringify(N.toTitle('')), O.toTitle('Size UserUsersize.'), '|', N.toTitle('Size UserUsersize.'));
const lk = [[['choi', 64], ['jung', -4], ['jung', 17], ['kim', 70], ['choi', 17], ['jung', 75]]];
console.log('lookup examples:', canon(O.toLookup(lk[0])), canon(N.toLookup(lk[0])));
for (const k of Object.keys(bad)) console.log(k, bad[k].length === 0 ? 'OK (50000 cases)' : `${bad[k].length} MISMATCH`, bad[k].slice(0, 3));
EOF
